mapper.delete:
DELETE FROM yglue_jar_library_class_method
WHERE class_id IN (
    SELECT id FROM yglue_jar_library_class WHERE jar_id = #{jarId}
);

DELETE FROM yglue_jar_library_class_field
WHERE class_id IN (
    SELECT id FROM yglue_jar_library_class WHERE jar_id = #{jarId}
);

mapper.select:
SELECT id, jar_id, qualified_name, simple_name, package_name, kind, doc FROM yglue_jar_library_class
qualified_name = #{qualifiedName}
AND jar_id IN
#{id}
ORDER BY jar_id LIMIT 1

SELECT id, class_id, name, type, is_static AS static
FROM yglue_jar_library_class_field
WHERE class_id = #{classId}
ORDER BY name
LIMIT #{limit} OFFSET #{offset}

SELECT id, class_id, name, return_type, is_static AS static, parameters_json
FROM yglue_jar_library_class_method
WHERE class_id = #{classId}
ORDER BY name
LIMIT #{limit} OFFSET #{offset}

SELECT id, jar_key, qualified_name, simple_name, package_name, kind, doc, fields_json, methods_json, created_at, updated_at FROM yglue_jar_class_agg
jar_key IN
#{key}
ORDER BY package_name, simple_name LIMIT #{limit}

SELECT id, jar_key, qualified_name, simple_name, package_name, kind, doc, fields_json, methods_json, created_at, updated_at FROM yglue_jar_class_agg
qualified_name = #{qualifiedName}
AND jar_key IN
#{key}
ORDER BY jar_key LIMIT 1

